before:
Complete local Rust example; the app itself does not execute it:
```rust
use std::sync::Arc;
use std::thread;

fn main() {
    let value = Arc::new(7);
    let worker = thread::spawn(move || *value);
    println!("{}", worker.join().expect("worker panicked"));
}
```

